mapper.select:
SELECT  FROM mk_resource_account
WHERE tenant_id = #{tenantId} AND resource_key = #{resourceKey}
FOR UPDATE

mapper.update:
UPDATE mk_resource_account
SET fencing_epoch = #{fencingEpoch}, version_no = #{versionNo}, state_name = #{stateName},
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId} AND resource_key = #{resourceKey}
  AND fencing_epoch = #{expectedFencingEpoch} AND version_no = #{expectedVersionNo}

UPDATE mk_resource_account
SET available_amount = #{availableAmount}, reserved_amount = #{reservedAmount},
    consumed_amount = #{consumedAmount}, returned_amount = #{returnedAmount},
    version_no = #{versionNo}, updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId} AND resource_key = #{resourceKey}
  AND version_no = #{expectedVersionNo}

mapper.select:
SELECT  FROM mk_benefit_definition
WHERE tenant_id = #{tenantId} AND benefit_id = #{benefitId}
ORDER BY version_no DESC LIMIT 1

SELECT status_name AS status, benefit_sku_id AS benefitSkuId, policy_json AS policyJson
FROM mk_benefit_definition
WHERE tenant_id = #{tenantId} AND benefit_id = #{benefitId} AND version_no = #{version}

SELECT latest_version FROM mk_benefit_definition_head
WHERE tenant_id = #{tenantId} AND benefit_id = #{benefitId}
FOR UPDATE

mapper.update:
UPDATE mk_resource_escrow_bucket
SET fencing_epoch = #{fencingEpoch}, state_name = #{stateName},
    version_no = version_no + 1, updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId} AND resource_key = #{resourceKey}
  AND fencing_epoch = #{expectedFencingEpoch}

UPDATE mk_resource_escrow_bucket
SET available_amount = available_amount - #{amount}, reserved_amount = reserved_amount + #{amount},
    version_no = version_no + 1, updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId} AND resource_key = #{resourceKey} AND bucket_id = #{bucketId}
  AND state_name = 'ACTIVE' AND fencing_epoch = #{fencingEpoch}
  AND available_amount >= #{amount}

mapper.select:
SELECT  FROM mk_resource_escrow_bucket
WHERE tenant_id = #{tenantId} AND resource_key = #{resourceKey}
ORDER BY bucket_id FOR UPDATE

SELECT  FROM mk_resource_escrow_bucket
WHERE tenant_id = #{tenantId} AND resource_key = #{resourceKey} AND bucket_id = #{bucketId}
FOR UPDATE

mapper.update:
UPDATE mk_resource_escrow_bucket
SET available_amount = #{available}, reserved_amount = #{reserved}, consumed_amount = #{consumed},
    returned_amount = #{returned}, version_no = #{version}, updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId} AND resource_key = #{resourceKey} AND bucket_id = #{bucketId}
  AND version_no = #{expectedVersion} AND fencing_epoch = #{fencingEpoch}

mapper.select:
SELECT tenant_id AS tenantId, application_id AS applicationId
FROM mk_promotion_application
WHERE state_name = 'RESERVED' AND expires_at <= #{now} AND expiry_next_attempt_at <= #{now}
AND tenant_id = #{tenantId}
ORDER BY expires_at LIMIT #{limit}

SELECT expiry_attempts FROM mk_promotion_application
WHERE tenant_id = #{tenantId} AND application_id = #{applicationId}
FOR UPDATE

