UPDATE mk_reservation_item


        SET reserved_amount = reserved_amount - #{amount}, consumed_amount = consumed_amount + #{amount}


        SET reserved_amount = reserved_amount - #{amount}, released_amount = released_amount + #{amount}


        SET consumed_amount = consumed_amount - #{amount}, refunded_amount = refunded_amount + #{amount}


WHERE tenant_id = #{tenantId} AND application_id = #{applicationId} AND resource_key = #{resourceKey}

    AND consumed_amount >= #{amount}
    AND reserved_amount >= #{amount}

UPDATE mk_reservation_escrow_allocation


        SET reserved_amount = reserved_amount - #{amount}, consumed_amount = consumed_amount + #{amount}


        SET reserved_amount = reserved_amount - #{amount}, released_amount = released_amount + #{amount}


        SET consumed_amount = consumed_amount - #{amount}, refunded_amount = refunded_amount + #{amount}


WHERE tenant_id = #{tenantId} AND application_id = #{applicationId} AND resource_key = #{resourceKey}
  AND bucket_id = #{bucketId}

